def hero_or_villain(string):
	if string.endswith('man'):
		return 'hero'
	else:
		return 'villain'
for _ in range(int(input())):
	n = int(input())
	a = []
	for i in range(n):
		a.append(input().strip())
	people = {'hero': 1, 'villain': 1}
	ans = 'draw'
	for i in a:
		people[hero_or_villain(i)] += 1
		if people['hero'] > people['villain'] + 1:
			ans = 'superheroes'
			break
		if people['hero'] + 2 < people['villain']:
			ans = 'villains'
			break
	print(ans)
